$token=bin2hex(random_bytes(16));$control=sys_get_temp_dir().'/aoou-private-bytes-'.$token;$root=$control.'/private';$remove=static function(string$path)use(&$remove):void{if(is_file($path)||is_link($path)){unlink($path);return;}if(!is_dir($path))return;foreach(scandir($path)?:[]as$entry)if($entry!=='.'&&$entry!=='..')$remove($path.'/'.$entry);rmdir($path);};
