try{mkdir($control,0700);mkdir($root,0700);$bytes="%PDF-1.4\nGate-5 durable original marker ".bin2hex(random_bytes(12))."\n%%EOF\n";$sha=hash('sha256',$bytes);$size=strlen($bytes);$storage=new AssignmentOrderOriginalFileStorage($root,$clock,$faults);$stage=$storage->beginStage();assertSameValue(AssignmentOrderOriginalStorageStatus::OK,$stage->write($bytes),'Accepted bytes are staged.');$outcome=$stage->finalize($sha,$size);assertSameValue(AssignmentOrderOriginalStorageStatus::OK,$outcome->status(),'Private finalize succeeds.');assertSameValue([$sha,$size],[$outcome->lease()?->content()?->sha256(),$outcome->lease()?->content()?->byteSize()],'Finalized evidence reports exact digest and received size.');assertSameValue(AssignmentOrderOriginalStorageStatus::OK,$outcome->lease()?->release(),'Content lease releases before restart.');unset($stage,$outcome,$storage);
    $command=[PHP_BINARY,dirname(__DIR__).'/Support/assignment_order_original_private_bytes_restart_probe.php',$root,$sha,(string)$size];$pipes=[];$process=proc_open($command,[1=>['pipe','w'],2=>['pipe','w']],$pipes);if(!is_resource($process))throw new TestFailure('Restart probe process could not start.');$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($process);assertSameValue([0,'',json_encode(['count'=>1,'sha256'=>$sha,'byteSize'=>$size],JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES)."\n"],[$exit,$stderr,$stdout],'Exactly one immutable private content file survives a fresh process with exact digest and size.');fwrite(STDOUT,"ASSIGNMENT_ORDER_ORIGINAL_PRIVATE_BYTES_RESTART_OK\n");
